abstract class Report {
    final String render() {
        return header() + "|" + body() + "|end";
    }
    String header() { return "H"; }
    abstract String body();
}

class Sales extends Report {
    @Override
    String header() { return "S"; }
    @Override
    String body() { return "sales"; }
}

System.out.println(new Sales().render());

