interface Document {
    String read();
    void write(String text);
    void delete();
}

class ArchivedDocument implements Document {
    public String read() { return "..."; }
    public void write(String text) { throw new UnsupportedOperationException(); }
    public void delete() { throw new UnsupportedOperationException(); }
}

String preview(Document doc) { return doc.read().substring(0, 3); }

